const D = { energy:.6, scale:1, density:.5, speed:1, warmth:.6, alpha:.78, hue:26, x:-.05, y:.78, style:'hearth', act:'burn', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const lrp=(a,b,t)=>a+(b-a)*t;
const md=(a,n)=>((a%n)+n)%n;
const frc=v=>v-Math.floor(v);
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const hsb2=(h,s,v)=>{h=md(h,360)/60;s=clp(s,0,1);v=clp(v,0,1);const c=v*s,x=c*(1-Math.abs(h%2-1)),m=v-c;let r=0,g=0,b=0;
  if(h<1){r=c;g=x;}else if(h<2){r=x;g=c;}else if(h<3){g=c;b=x;}else if(h<4){g=x;b=c;}else if(h<5){r=x;b=c;}else{r=c;b=x;}
  return [(r+m)*255,(g+m)*255,(b+m)*255];};

const W=width, Hh=height, u=Math.min(W,Hh);
const H=md(P.hue,360);
const st=P.style, act=P.act||'burn';
const isFrg=st==='forge', isCnd=st==='candle', isPho=st==='photometric', isWdc=st==='woodcut';
const en=clp(P.energy,0,1), dn=clp(P.density,0,1), al=clp(P.alpha,0,1), wm=clp(P.warmth,0,1);
const sc=clp(P.scale,0.4,2.2), sp=clp(P.speed,0.1,4);
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const MAXO=9;
if(S.seedUsed!==P.seed||!S.oc){
  S.seedUsed=P.seed;
  S.nt=new Float32Array(257);
  for(let i=0;i<256;i++) S.nt[i]=fr(i*2.13+7.7);
  S.nt[256]=S.nt[0];
  S.oc=[];
  for(let k=0;k<MAXO;k++){
    const thin=fr(k*31+5)>0.55;
    S.oc.push({
      th0: fr(k*3+1)*6.2832,
      dr: (0.016+fr(k*5+2)*0.042)*(fr(k*7+3)>0.5?1:-1),   // each occluder pivots at its own rate
      wob: 0.05+fr(k*11+4)*0.19,
      wr: [0.37,0.61,0.97][k%3]*(0.7+fr(k*13+6)*0.6),      // incommensurate wobble rates
      w: thin ? 0.022+fr(k*17+7)*0.038 : 0.075+fr(k*19+8)*0.20,
      d: thin ? 0.55+fr(k*23+9)*0.40 : 0.40+fr(k*29+10)*0.48,
      r0: 0.05+fr(k*37+11)*0.30
    });
  }
  S.ph=[fr(91)*6.2832,fr(93)*6.2832,fr(95)*6.2832];
}
const NT=S.nt;
const n1=x=>{const f=x-Math.floor(x); const i=((Math.floor(x)%256)+256)%256; return NT[i]+(NT[i+1]-NT[i])*(f*f*(3-2*f));};

// ---- fire output: slow breathe + a SHALLOW gutter. Never a strobe: gutter <= 12% amplitude. ----
const gutAmp=0.055+0.062*en;
const gut=1+gutAmp*(0.56*Math.sin(K.t*1.27*sp+S.ph[0])+0.30*Math.sin(K.t*2.31*sp+S.ph[1])+0.14*Math.sin(K.t*3.71*sp+S.ph[2]));
const breathe=0.80+0.28*(0.62*Math.sin(K.t*0.17*sp+0.4)+0.38*Math.sin(K.t*0.41*sp+1.9));
let out=1, radM=1;
if(act==='flare_up'){ const f=Math.pow(clp(0.5+0.5*Math.sin(K.t*0.043*sp),0,1),2.4); out=0.72+1.05*f; radM=1+0.30*f; }
else if(act==='dying'){ const f=Math.pow(clp(0.5+0.5*Math.sin(K.t*0.021*sp+1.4),0,1),1.3); out=0.28+1.05*f; radM=0.62+0.55*f; }
else { out=0.90+0.26*(0.6*Math.sin(K.t*0.107*sp+2.2)+0.4*Math.sin(K.t*0.233*sp+0.7)); radM=1+0.10*Math.sin(K.t*0.163*sp)+0.05*Math.sin(K.t*0.077*sp+1.4); }
const arc=0.72+0.55*K.intensity;
const OUT=out*breathe*gut*arc*(0.52+0.80*en)*(1+A.bass*0.30);
const R=u*(0.58+0.52*en)*sc*radM*(isCnd?0.80:1);

// ---- source centroid wanders (incommensurate) — the whole wash translates, not just dims ----
const SX=(clp(P.x,-0.3,1.3)+0.045*Math.sin(K.t*0.113*sp)+0.024*Math.sin(K.t*0.29*sp+1.2))*W;
const SY=(clp(P.y,-0.3,1.3)+0.036*Math.sin(K.t*0.097*sp+0.8)+0.019*Math.sin(K.t*0.241*sp+2.6))*Hh;
const nOc=Math.max(1,Math.round(lrp(2,MAXO,dn)));
const t=K.t*sp;

// ---- occluder angles this frame ----
const OT=[], OW=[], OD=[], OR=[];
for(let k=0;k<nOc;k++){
  const o=S.oc[k];
  OT.push(o.th0+o.dr*t+o.wob*Math.sin(t*o.wr+o.th0));
  OW.push(o.w*(0.6+0.9*sc));
  OD.push(o.d*(0.35+0.75*en));
  OR.push(o.r0*R);
}

const bw=164, bh=clp(Math.round(164*Hh/W),60,200);
if(!S.g||S.bw!==bw||S.bh!==bh){ S.g=createGraphics(bw,bh); S.g.pixelDensity(1); S.bw=bw; S.bh=bh; }
const g=S.g;
g.loadPixels();
const pix=g.pixels;
const wobA=(0.05+0.13*en)*(isCnd?0.85:1);
for(let yy=0;yy<bh;yy++){
  const py=(yy+0.5)/bh*Hh;
  for(let xx=0;xx<bw;xx++){
    const px=(xx+0.5)/bw*W;
    const dx=px-SX, dy=py-SY;
    const r=Math.sqrt(dx*dx+dy*dy);
    const rn=r/R;
    let L=1/(1+rn*rn*(isCnd?2.5:1.9));                    // inverse-square-ish throw
    if(L<0.004){ pix[4*(yy*bw+xx)+3]=0; continue; }
    let th=Math.atan2(dy,dx);
    // heat wobble in the near field: the shadow edges shiver, they never flicker
    if(rn<0.85) th+=(n1(rn*9.3-t*1.9)-0.5)*wobA*(1-rn/0.85);
    let occ=1;
    for(let k=0;k<nOc;k++){
      if(r<OR[k]) continue;
      let ad=th-OT[k];
      ad=md(ad+Math.PI,6.2832)-Math.PI;
      const we=OW[k]*(1+rn*1.5);                          // penumbra widens with distance from the light
      const qq=ad/we;
      if(qq>-1&&qq<1){ const s2=1-qq*qq; occ*=1-OD[k]*s2*s2; }
    }
    L*=occ*OUT;
    const e=clp(L,0,1);
    let hh,ss,vv,aa;
    if(isFrg){
      hh=e<0.10?H+lrp(210,40,e/0.10):H+lrp(40,26,Math.pow(clp((e-0.10)/0.9,0,1),0.5));
      ss=e<0.10?lrp(0.55,0.98,e/0.10):lrp(0.98,0.04,Math.pow(clp((e-0.10)/0.9,0,1),1.05))*(0.4+0.65*wm);
      vv=lrp(0.07,1,Math.pow(e,0.52)); aa=clp(L*1.35,0,0.96);
    } else if(isPho){
      const q=Math.min(6,Math.floor(e*7)), edge=Math.abs(frc(e*7)*2-1);
      hh=H+lrp(196,168,q/6); ss=lrp(0.66,0.30,q/6);
      vv=0.24+0.10*q+0.58*Math.pow(edge,5);
      aa=clp(0.10+q*0.115+0.34*Math.pow(edge,5),0,0.9);
    } else if(isWdc){
      const q=e<0.15?0:e<0.40?1:e<0.70?2:3;
      const grain=n1(px*0.09+py*0.05+3.1)>0.19?1:0.55;
      hh=H+lrp(-10,34,q/3); ss=lrp(0.88,0.12,q/3)*(0.4+0.7*wm);
      vv=[0.05,0.30,0.64,0.97][q]; aa=[0,0.68,0.86,0.96][q]*grain;
    } else {
      hh=H+lrp(-16,24,Math.pow(e,0.6));
      ss=lrp(0.96,0.14,Math.pow(e,1.5))*(0.35+0.72*wm);
      vv=lrp(0.06,1,Math.pow(e,isCnd?0.60:0.72));
      aa=clp(L*(isCnd?1.5:1.2),0,0.95);
    }
    const col=hsb2(hh,ss,vv);
    const pp=4*(yy*bw+xx);
    pix[pp]=col[0]; pix[pp+1]=col[1]; pix[pp+2]=col[2]; pix[pp+3]=clp(aa,0,1)*255;
  }
}
g.updatePixels();

// ---- the wash goes down additively so it reads as LIGHT, not paint, over any bed ----
blendMode(ADD);
tint(0,0,100,clp(al*(isPho?0.9:1),0,1)*100);
image(g,0,0,W,Hh);
noTint();

// ---- soft bloom around the source: few shapes, shadowBlur, always reset ----
if(!isPho&&SX>-R*0.4&&SX<W+R*0.4&&SY>-R*0.4&&SY<Hh+R*0.4){
  noStroke();
  drawingContext.shadowBlur=R*0.20;
  drawingContext.shadowColor='rgba(255,190,110,0.45)';
  fill(H+18,lrp(50,10,en)*(0.4+0.7*wm),100,clp(20*al*OUT,0,30));
  circle(SX,SY,R*0.30*(1+0.10*Math.sin(K.t*0.83*sp)+0.06*Math.sin(K.t*1.93*sp+1.1)));
  drawingContext.shadowBlur=0;
}
blendMode(BLEND);

// ---- photometric furniture: iso-lux callouts, an instrument not a picture ----
if(isPho){
  noStroke(); fill(H+186,20,100,clp(60*al,0,72));
  textAlign(LEFT,BOTTOM); textSize(Math.max(8,u*0.017));
  const lab=['0.5','2','8','32','128'];
  for(let i=0;i<5;i++){
    const e=(i+1)/6;
    const rr=R*Math.sqrt(clp(1/Math.max(1e-3,e/Math.max(0.05,OUT))-1,0,80)/1.9);
    if(!isFinite(rr)||rr<u*0.04||rr>u*2.6) continue;
    const a=-0.55+i*0.16;
    const lx=SX+Math.cos(a)*rr, ly=SY+Math.sin(a)*rr;
    if(lx<0||lx>W||ly<0||ly>Hh) continue;
    text(lab[i]+' lx',lx,ly);
  }
}

blendMode(BLEND); drawingContext.shadowBlur=0; noTint();
